-- ============================================================
-- MARPEX — Plano de Contas: Blocos 2 (Aquisições) e 4 (Operacional)
-- Execute no SQL Editor do Supabase
-- ------------------------------------------------------------
-- Segunda etapa do Plano de Contas de Exportação (PDF "MARPEX - PLANO
-- DE CONTAS"). Pelo próprio plano, a Versão 1 = Blocos 1, 2 e 4; o
-- Bloco 1 (Receitas) já está no ar (database-plano-contas-receitas.sql).
-- Decidido com o usuário em 2026-10-20: Blocos 2 e 4 entram juntos em
-- Contas a Pagar; o controle Previsto × Revisado × Pago fica para depois.
--
-- Reaproveita a mesma tabela plano_contas (só linhas novas com bloco 2 e
-- 4). Códigos 4.10–4.13 do PDF foram padronizados como 04.10–04.13; os
-- ajustes ficam como 4.90 (igual ao 1.90 do Bloco 1).
-- Idempotente.
-- ============================================================

ON CONFLICT (codigo) DO NOTHING;

-- Contas a Pagar passa a ser classificada pelo plano (a coluna antiga
-- `categoria` continua existindo para os lançamentos antigos).
ALTER TABLE contas_pagar ADD COLUMN IF NOT EXISTS plano_conta_id UUID REFERENCES plano_contas(id);
CREATE INDEX IF NOT EXISTS idx_contas_pagar_plano_conta ON contas_pagar(plano_conta_id);

-- Verificação: 44 contas no Bloco 2 e 114 no Bloco 4
SELECT bloco, bloco_nome, count(*) AS contas FROM plano_contas GROUP BY bloco, bloco_nome ORDER BY bloco;
